void Args::parse(int argc,char**argv){
 string cmd=argv[1]; if(cmd=="supervised")supervised();else if(cmd=="cbow")model=1;
 auto fail=[&](string s){cerr<<s<<"\n\n";help(cerr);exit(1);};
 for(int i=2;i<argc;i++){
  string k=argv[i];
  if(k.empty()||k[0]!='-')fail("Provided argument without a dash! Usage:");
  if(k=="-h")fail("Here is the help! Usage:");
  if(k=="-saveOutput"){saveOutput=true;continue;}
  if(k=="-retrain"){retrain=true;continue;}
  if(k=="-qnorm"){qnorm=true;continue;}
  if(k=="-qout"){qout=true;continue;}
  set<string> names={"-input","-output","-lr","-lrUpdateRate","-dim","-ws","-epoch","-minCount","-minCountLabel","-neg","-wordNgrams","-loss","-bucket","-minn","-maxn","-thread","-t","-label","-verbose","-pretrainedVectors","-seed","-cutoff","-dsub","-autotune-validation","-autotune-metric","-autotune-predictions","-autotune-duration","-autotune-modelsize"};
  if(!names.count(k))fail("Unknown argument: "+k);
  if(i+1==argc)fail(k+" is missing an argument");
  string v=argv[++i];
  if(k=="-input")input=v; else if(k=="-output")output=v; else if(k=="-lr")lr=stof(v);
  else if(k=="-lrUpdateRate")lrUpdateRate=stoi(v); else if(k=="-dim")dim=stoi(v);
  else if(k=="-ws")ws=stoi(v);else if(k=="-epoch")epoch=stoi(v);else if(k=="-minCount")minCount=stoi(v);
  else if(k=="-minCountLabel")minCountLabel=stoi(v);else if(k=="-neg")neg=stoi(v);
  else if(k=="-wordNgrams")wordNgrams=stoi(v);else if(k=="-bucket")bucket=stoi(v);
  else if(k=="-minn")minn=stoi(v);else if(k=="-maxn")maxn=stoi(v);else if(k=="-thread")thread=stoi(v);
  else if(k=="-t")t=stof(v);else if(k=="-label")label=v;else if(k=="-verbose")verbose=stoi(v);
  else if(k=="-pretrainedVectors")pretrainedVectors=v;else if(k=="-seed")seed=stoi(v);
  else if(k=="-cutoff")cutoff=stoi(v);else if(k=="-dsub")dsub=stoi(v);
  else if(k=="-autotune-validation")autotuneValidation=v;
  else if(k=="-autotune-metric"){
   autotuneMetric=v;
   if(v!="f1"&&v.rfind("f1:",0)!=0&&v.rfind("precisionAtRecall:",0)!=0&&v.rfind("recallAtPrecision:",0)!=0)throw runtime_error("Unknown metric : "+v);
  }
  else if(k=="-autotune-modelsize")autotuneModelsize=v;
  else if(k=="-autotune-duration")autotuneDuration=stoi(v);
  else if(k=="-autotune-predictions")autotunePredictions=stoi(v);
  else if(k=="-loss"){
   if(v=="hs")loss=1;else if(v=="ns")loss=2;else if(v=="softmax")loss=3;else if(v=="ova"||v=="one-vs-all")loss=4;else fail("Unknown loss: "+v);
  }
 }
 if(input.empty()||output.empty())fail("Empty input or output path.");
 if(wordNgrams<=1&&maxn==0)bucket=0;
}

template<class T> void put(ostream&o,const T&v){o.write(reinterpret_cast<const char*>(&v),sizeof(v));}
template<class T> T get(istream&i){T v{};i.read(reinterpret_cast<char*>(&v),sizeof(v));return v;}
uint32_t hashWord(const string&s){uint32_t h=2166136261u;for(unsigned char c:s){h^=uint32_t(int32_t(int8_t(c)));h*=16777619u;}return h;}
bool readWord(istream&in,string&w){
 w.clear(); char c;
 while(in.get(c)){
  if(c==' '||c=='\n'||c=='\r'||c=='\t'||c=='\v'||c=='\f'||c==0){
   if(w.empty()){if(c=='\n'){w="</s>";return true;}}
   else {if(c=='\n')in.unget();return true;}
  }else w.push_back(c);
 }
 return !w.empty();
}
struct Entry {string word;int64_t count=0;int8_t type=0;vector<int> sub;};
struct Dictionary {
 Args *a; vector<Entry> words;unordered_map<string,int> ids;
 int nwords=0,nlabels=0;int64_t ntokens=0,pruneSize=-1;unordered_map<int,int> prune;
 explicit Dictionary(Args*arg):a(arg){}
 int id(const string&s)const{auto i=ids.find(s);return i==ids.end()?-1:i->second;}
 bool isLabel(const string&w)const{return w.rfind(a->label,0)==0;}
 void add(const string&w){int i=id(w);if(i<0){ids[w]=words.size();Entry e;e.word=w;e.count=1;e.type=isLabel(w)?1:0;words.push_back(move(e));}else words[i].count++;}
 void threshold(int wc,int lc){
  sort(words.begin(),words.end(),[](const Entry&x,const Entry&y){return x.type!=y.type?x.type<y.type:x.count>y.count;});
  words.erase(remove_if(words.begin(),words.end(),[&](const Entry&e){return e.count<(e.type?lc:wc);}),words.end());
  ids.clear();nwords=nlabels=0;for(int i=0;i<(int)words.size();i++){ids[words[i].word]=i;if(words[i].type)nlabels++;else nwords++;}
 }
 int bucketIndex(uint64_t h)const{
  if(a->bucket<=0)return -1;
  int b=h%a->bucket;
  if(pruneSize>=0){auto it=prune.find(b);if(it==prune.end())return -1;b=it->second;}
  return nwords+b;
 }
 void ngrams(const string&word,vector<int>&sub,vector<string>*names=nullptr)const{
  if(a->maxn<=0)return;
  string s="<"+word+">";
  for(size_t i=0;i<s.size();i++){
   if((static_cast<unsigned char>(s[i])&0xc0)==0x80)continue;
   string n;
   for(size_t j=i,sz=1;j<s.size()&&sz<=size_t(max(a->maxn,0));sz++){
    n.push_back(s[j++]);while(j<s.size()&&(static_cast<unsigned char>(s[j])&0xc0)==0x80)n.push_back(s[j++]);
    if(int(sz)>=a->minn&&!(sz==1&&(i==0||j==s.size()))){int idx=bucketIndex(hashWord(n));if(idx>=0){sub.push_back(idx);if(names)names->push_back(n);}}
   }
  }
 }
 void init(){for(int i=0;i<(int)words.size();i++){words[i].sub={i};if(words[i].word!="</s>")ngrams(words[i].word,words[i].sub);}}
 vector<int> subwords(const string&w)const{int i=id(w);if(i>=0)return words[i].sub;vector<int>v;if(w!="</s>")ngrams(w,v);return v;}
 void read(istream&in){string w;while(readWord(in,w)){add(w);ntokens++;}threshold(a->minCount,a->minCountLabel);if(a->verbose>0){cerr<<"\rRead "<<ntokens/1000000<<"M words\nNumber of words:  "<<nwords<<"\nNumber of labels: "<<nlabels<<"\n";}if(words.empty())throw invalid_argument("Empty vocabulary. Try a smaller -minCount value.");init();}
 void save(ostream&o)const{put<int32_t>(o,words.size());put<int32_t>(o,nwords);put<int32_t>(o,nlabels);put(o,ntokens);put(o,pruneSize);for(auto&e:words){o.write(e.word.c_str(),e.word.size()+1);put(o,e.count);put(o,e.type);}for(auto&p:prune){put<int32_t>(o,p.first);put<int32_t>(o,p.second);}}
 void load(istream&in){int sz=get<int32_t>(in);nwords=get<int32_t>(in);nlabels=get<int32_t>(in);ntokens=get<int64_t>(in);pruneSize=get<int64_t>(in);if(sz<0||sz>100000000)throw invalid_argument("Invalid dictionary.");words.resize(sz);for(int i=0;i<sz;i++){getline(in,words[i].word,'\0');words[i].count=get<int64_t>(in);words[i].type=get<int8_t>(in);ids[words[i].word]=i;}for(int64_t i=0;i<pruneSize;i++){int x=get<int32_t>(in),y=get<int32_t>(in);prune[x]=y;}init();}
 void wordNgrams(vector<int>&v,const vector<uint32_t>&hashes)const{for(size_t i=0;i<hashes.size();i++){uint64_t h=hashes[i];for(size_t j=i+1;j<hashes.size()&&j<i+max(a->wordNgrams,0);j++){h=h*116049371ull+hashes[j];int idx=bucketIndex(h);if(idx>=0)v.push_back(idx);}}}
 // The supervised reader keeps hashes of unknown words for word n-grams.
 int line(istream&in,vector<int>&v,vector<int>&labels)const{
  v.clear();labels.clear();vector<uint32_t> hashes;string w;int count=0;
  while(readWord(in,w)){
   count++;int i=id(w);bool lab=i>=0?words[i].type:isLabel(w);
   if(lab){if(i>=0)labels.push_back(i-nwords);}
   else {if(i>=0)v.insert(v.end(),words[i].sub.begin(),words[i].sub.end());else if(w!="</s>")ngrams(w,v);hashes.push_back(hashWord(w));}
   if(w=="</s>")break;
  }
  wordNgrams(v,hashes);return count;
 }
};

struct Matrix {
 int64_t m=0,n=0;vector<float>x;
 Matrix(){}Matrix(int64_t r,int64_t c){resize(r,c);}
 void resize(int64_t r,int64_t c){m=r;n=c;if(r<0||c<0||r>100000000||c>1000000||r*c>1000000000)throw bad_alloc();x.assign(r*c,0);}
 float* row(int64_t i){return x.data()+i*n;}const float* row(int64_t i)const{return x.data()+i*n;}
 void initUniform(int seed,int threads){
  int64_t block=m*n/10;
  for(int p=0;p<min(threads,100);p++){
   minstd_rand rng(seed+p);uniform_real_distribution<double>d(-1.0/n,1.0/n);
   for(int64_t j=p*block;j<min<int64_t>((p+1)*block,m*n);j++)x[j]=d(rng);
  }
 }
 void save(ostream&o)const{put(o,m);put(o,n);o.write(reinterpret_cast<const char*>(x.data()),x.size()*sizeof(float));}
 void load(istream&i){int64_t r=get<int64_t>(i),c=get<int64_t>(i);resize(r,c);i.read(reinterpret_cast<char*>(x.data()),x.size()*sizeof(float));}
 void dump(ostream&o)const{o<<m<<" "<<n<<"\n";for(int64_t i=0;i<m;i++){for(int64_t j=0;j<n;j++){if(j)o<<" ";o<<row(i)[j];}o<<"\n";}}
};
void addVector(vector<float>&v,const float*x,float scale=1){for(size_t j=0;j<v.size();j++)v[j]+=scale*x[j];}
void mulVector(vector<float>&v,float scale){for(float&f:v)f*=scale;}
float dot(const float*a,const float*b,int n){float r=0;for(int j=0;j<n;j++)r+=a[j]*b[j];return r;}
float norm(const vector<float>&v){return sqrt(dot(v.data(),v.data(),v.size()));}
void printVector(ostream&o,const vector<float>&v){o<<setprecision(5);for(float f:v)o<<f<<" ";o<<"\n";}
struct Node {int parent=-1,left=-1,right=-1;int64_t count=0;bool binary=false;};
struct Model {
 Args a;Dictionary d;Matrix input,output;bool quant=false,qout=false;
 vector<Node> tree;vector<vector<int>> paths,codes;
 Model():d(&a){}
 void save(const string&path)const;
 void load(const string&path);
 void train();
 vector<float> wordVector(const string&w)const {vector<float>v(a.dim,0);auto sw=d.subwords(w);for(int i:sw)if(i>=0&&i<input.m)addVector(v,input.row(i));if(!sw.empty())mulVector(v,1.0/sw.size());return v;}
 vector<float> hidden(const vector<int>&ids)const {vector<float>v(a.dim,0);for(int i:ids)if(i>=0&&i<input.m)addVector(v,input.row(i));if(!ids.empty())mulVector(v,1.0/ids.size());return v;}
 vector<float> sentence(istream&in)const;
 void buildTree();
 vector<pair<float,int>> predict(const vector<int>&ids,int k,float th)const;
 void saveVectors(const string&path,bool out=false)const;
};
void Model::save(const string&path)const{
 ofstream o(path,ios::binary);if(!o)throw invalid_argument(path+" cannot be opened for saving.");
 put<int32_t>(o,793712314);put<int32_t>(o,12);
 for(int v:{a.dim,a.ws,a.epoch,a.minCount,a.neg,a.wordNgrams,a.loss,a.model,a.bucket,a.minn,a.maxn,a.lrUpdateRate})put<int32_t>(o,v);
 put(o,a.t);d.save(o);put<uint8_t>(o,0);input.save(o);put<uint8_t>(o,0);output.save(o);
}
void Model::load(const string&path){
 ifstream in(path,ios::binary);if(!in)throw invalid_argument(path+" cannot be opened for loading!");
 int magic=get<int32_t>(in),version=get<int32_t>(in);if(magic!=793712314||version>12)throw invalid_argument(path+" has wrong file format!");
 a.dim=get<int32_t>(in);a.ws=get<int32_t>(in);a.epoch=get<int32_t>(in);a.minCount=get<int32_t>(in);a.neg=get<int32_t>(in);a.wordNgrams=get<int32_t>(in);a.loss=get<int32_t>(in);a.model=get<int32_t>(in);a.bucket=get<int32_t>(in);a.minn=get<int32_t>(in);a.maxn=get<int32_t>(in);a.lrUpdateRate=get<int32_t>(in);a.t=get<double>(in);
 if(version==11&&a.model==3)a.maxn=0;
 d.load(in);quant=get<uint8_t>(in);if(quant)throw invalid_argument("Unsupported quantized model.");input.load(in);qout=get<uint8_t>(in);output.load(in);buildTree();
}
void Model::saveVectors(const string&path,bool out)const{
 ofstream f(path);if(!f)throw invalid_argument(path+" cannot be opened for saving.");
 int m=out?output.m:d.nwords;f<<m<<" "<<a.dim<<"\n";
 for(int i=0;i<m;i++){f<<d.words[i+(out&&a.model==3?d.nwords:0)].word<<" ";vector<float>v;if(out)v.assign(output.row(i),output.row(i)+a.dim);else v=wordVector(d.words[i].word);printVector(f,v);}
}
void Model::buildTree(){
 int n=output.m;tree.assign(max(0,2*n-1),Node{});paths.assign(n,{});codes.assign(n,{});if(!n)return;
 for(int i=0;i<n;i++)tree[i].count=d.words[i+(a.model==3?d.nwords:0)].count;
 for(int i=n;i<2*n-1;i++)tree[i].count=int64_t(1e15);
 int leaf=n-1,node=n;
 for(int i=n;i<2*n-1;i++){
  int mini[2];for(int j=0;j<2;j++){if(leaf>=0&&tree[leaf].count<tree[node].count)mini[j]=leaf--;else mini[j]=node++;}
  tree[i].left=mini[0];tree[i].right=mini[1];tree[i].count=tree[mini[0]].count+tree[mini[1]].count;
  tree[mini[0]].parent=i;tree[mini[1]].parent=i;tree[mini[1]].binary=true;
 }
 for(int i=0;i<n;i++){int j=i;while(tree[j].parent>=0){paths[i].push_back(tree[j].parent-n);codes[i].push_back(tree[j].binary);j=tree[j].parent;}}
}
vector<float> Model::sentence(istream&in)const{
 if(a.model==3){vector<int>w,l;d.line(in,w,l);return hidden(w);}
 string line;getline(in,line);istringstream s(line);string w;vector<float>v(a.dim,0);int n=0;
 while(s>>w){auto x=wordVector(w);float z=norm(x);if(z>0){mulVector(x,1/z);addVector(v,x.data());n++;}}
 if(n)mulVector(v,1.0/n);return v;
}
vector<pair<float,int>> Model::predict(const vector<int>&ids,int k,float th)const{
 if(a.model!=3)throw invalid_argument("Model needs to be supervised for prediction!");
 if(k==-1)k=output.m;if(k<=0)throw invalid_argument("k needs to be 1 or higher!");
 vector<pair<float,int>>result;if(ids.empty()||output.m==0)return result;
 auto h=hidden(ids);vector<float>p(output.m);
 if(a.loss==1){
  function<void(int,float)> dfs=[&](int node,float sc){if(node<output.m){if(exp(sc)>=th)result.emplace_back(sc,node);return;}float f=dot(h.data(),output.row(node-output.m),a.dim);float pr=1.0/(1.0+exp(-f));dfs(tree[node].left,sc+log(1.0-pr+1e-5));dfs(tree[node].right,sc+log(pr+1e-5));};
  dfs(2*output.m-2,0);
 }else{
  for(int i=0;i<output.m;i++)p[i]=dot(output.row(i),h.data(),a.dim);
  if(a.loss==3){float mx=*max_element(p.begin(),p.end()),sum=0;for(float&f:p){f=exp(f-mx);sum+=f;}for(float&f:p)f/=sum;}
  else for(float&f:p)f=1.0/(1.0+exp(-f));
  for(int i=0;i<output.m;i++)if(!(p[i]<th))result.emplace_back(log(p[i]+1e-5),i);
 }
 sort(result.begin(),result.end(),greater<pair<float,int>>());if(result.size()>(size_t)k)result.resize(k);return result;
}

struct Trainer {
 Model&m;Args&a;Dictionary&d;minstd_rand rng;vector<int> negatives;vector<float>sigmoidTable,logTable;double loss=0;int64_t updates=0;
 Trainer(Model&mod,int seed):m(mod),a(mod.a),d(mod.d),rng(seed){
  sigmoidTable.resize(513);logTable.resize(513);for(int i=0;i<=512;i++){float x=float(i*2*8)/512-8;sigmoidTable[i]=1.0/(1.0+exp(-x));logTable[i]=log((i+1e-5)/512.0);}
  if(a.loss==2&&m.output.m>0){double sum=0;for(int i=0;i<m.output.m;i++)sum+=sqrt(d.words[i+(a.model==3?d.nwords:0)].count);for(int i=0;i<m.output.m;i++){double n=sqrt(d.words[i+(a.model==3?d.nwords:0)].count)*10000000/sum;for(int j=0;j<n;j++)negatives.push_back(i);}}
 }
 float sigmoid(float x){if(x<-8)return 0;if(x>8)return 1;return sigmoidTable[int((x+8)*512/16)];}
 float fastlog(float x){if(x>1)return 0;return logTable[max(0,min(512,int(x*512)))];}
 float binary(int target,bool label,float lr,const vector<float>&h,vector<float>&grad){
  float*row=m.output.row(target);float sc=dot(row,h.data(),a.dim);if(isnan(sc))throw fasttext::DenseMatrix::EncounteredNaNError();float p=sigmoid(sc);float alpha=lr*(float(label)-p);addVector(grad,row,alpha);for(int j=0;j<a.dim;j++)row[j]+=alpha*h[j];return label?-fastlog(p):-fastlog(1-p);
 }
 void update(const vector<int>&ids,const vector<int>&labels,int target,float lr){
  if(ids.empty())return;
  auto h=m.hidden(ids);vector<float>grad(a.dim,0);float L=0;
  if(a.loss==3){
   vector<float>p(m.output.m);float mx=-numeric_limits<float>::infinity();for(int i=0;i<m.output.m;i++){p[i]=dot(m.output.row(i),h.data(),a.dim);if(isnan(p[i]))throw fasttext::DenseMatrix::EncounteredNaNError();mx=max(mx,p[i]);}
   float sum=0;for(float&f:p){f=exp(f-mx);sum+=f;}for(float&f:p)f/=sum;
   for(int i=0;i<m.output.m;i++){float alpha=lr*((i==target?1.f:0.f)-p[i]);float*row=m.output.row(i);addVector(grad,row,alpha);for(int j=0;j<a.dim;j++)row[j]+=alpha*h[j];}
   L=-fastlog(p[target]);
  }else if(a.loss==2){
   L+=binary(target,true,lr,h,grad);if(m.output.m>1){uniform_int_distribution<size_t>pick(0,negatives.size()-1);for(int i=0;i<a.neg;i++){int n;do{n=negatives[pick(rng)];}while(n==target);L+=binary(n,false,lr,h,grad);}}
  }else if(a.loss==1){for(size_t i=0;i<m.paths[target].size();i++)L+=binary(m.paths[target][i],m.codes[target][i],lr,h,grad);}
  else {for(int i=0;i<m.output.m;i++){bool positive=find(labels.begin(),labels.end(),i)!=labels.end();L+=binary(i,positive,lr,h,grad);}}
  if(a.model==3)mulVector(grad,1.0/ids.size());for(int i:ids)if(i>=0&&i<m.input.m){float*row=m.input.row(i);for(int j=0;j<a.dim;j++)row[j]+=grad[j];}
  loss+=L;updates++;
 }
 int unsupLine(istream&in,vector<int>&line){
  line.clear();string w;int nt=0;uniform_real_distribution<double>unif(0,1);
  while(readWord(in,w)){
   int i=d.id(w);if(i<0)continue;nt++;
   if(i<d.nwords){double f=double(d.words[i].count)/d.ntokens;double p=sqrt(a.t/f)+a.t/f;if(unif(rng)<=p)line.push_back(i);}
   if(nt>1024||w=="</s>")break;
  }
  return nt;
 }
 void trainLine(istream&in,float lr,int&count){
  vector<int>v,l;
  if(a.model==3){count=d.line(in,v,l);if(l.empty()||v.empty())return;int target=0;if(a.loss!=4){uniform_int_distribution<int>pick(0,l.size()-1);target=l[pick(rng)];}update(v,l,target,lr);}
  else {
   count=unsupLine(in,v);uniform_int_distribution<int>boundary(1,max(1,a.ws));
   for(int w=0;w<(int)v.size();w++){
    int b=boundary(rng);
    if(a.model==2){for(int c=-b;c<=b;c++){if(c==0||w+c<0||w+c>=(int)v.size())continue;update(d.words[v[w]].sub,{},v[w+c],lr);}}
    else {vector<int>ng;for(int c=-b;c<=b;c++){if(c==0||w+c<0||w+c>=(int)v.size())continue;auto&s=d.words[v[w+c]].sub;ng.insert(ng.end(),s.begin(),s.end());}update(ng,{},v[w],lr);}
   }
  }
 }
};
void Model::train(){
 // Output paths are checked before the training corpus is opened.
 {ofstream check(a.output+".bin",ios::binary);if(!check)throw invalid_argument(a.output+".bin cannot be opened for saving.");}
 if(a.input=="-")throw invalid_argument("Cannot use stdin for training!");
 ifstream data(a.input);if(!data)throw invalid_argument(a.input+" cannot be opened for training!");
 d.read(data);
 input.resize(d.nwords+(int64_t)a.bucket,a.dim);input.initUniform(a.seed,a.thread);output.resize(a.model==3?d.nlabels:d.nwords,a.dim);
 if(!a.pretrainedVectors.empty()){
  ifstream p(a.pretrainedVectors);if(!p)throw invalid_argument(a.pretrainedVectors+" cannot be opened for loading!");int64_t n;int dim;p>>n>>dim;if(dim!=a.dim)throw invalid_argument("Dimension of pretrained vectors does not match -dim option");
  string w;for(int64_t i=0;i<n;i++){p>>w;int idx=d.id(w);for(int j=0;j<dim;j++){float f=0;p>>f;if(idx>=0&&idx<input.m)input.row(idx)[j]=f;}}
 }
 buildTree();
 Trainer trainer(*this,a.seed);int64_t tokens=0,local=0,total=a.epoch*d.ntokens;
 data.clear();data.seekg(0);auto start=chrono::steady_clock::now();
 if(a.thread>0){
  while(tokens<total){
   float progress=float(tokens)/total;float lr=a.lr*(1.0-progress);int count=0;
   if(data.eof()){data.clear();data.seekg(0);}
   trainer.trainLine(data,lr,count);local+=count;
   if(local>a.lrUpdateRate){tokens+=local;local=0;}
   if(count==0&&d.ntokens==0)break;
  }
 }
 if(a.verbose>0){
  double duration=chrono::duration<double>(chrono::steady_clock::now()-start).count();double speed=duration>0?tokens/duration/max(a.thread,1):0;
  cerr<<"\rProgress: 100.0% words/sec/thread: "<<setw(7)<<fixed<<setprecision(0)<<speed<<" lr:  0.000000 avg.loss: "<<setw(9)<<setprecision(6)<<(trainer.updates?trainer.loss/trainer.updates:-numeric_limits<double>::quiet_NaN())<<" ETA:   0h 0m 0s\n";
 }
 save(a.output+".bin");saveVectors(a.output+".vec");if(a.saveOutput)saveVectors(a.output+".output",true);
}

void shortHelp(const string&cmd){
 ostream&o=(cmd=="nn"||cmd=="analogies"||cmd=="dump")?cout:cerr;
 if(cmd=="test"||cmd=="test-label"||cmd=="predict"||cmd=="predict-prob"){
  string name=(cmd=="predict"||cmd=="predict-prob")?"predict[-prob]":cmd;
  o<<"usage: fasttext "<<name<<" <model> <test-data> [<k>] [<th>]\n\n"
  "  <model>      model filename\n  <test-data>  test data filename"<<(cmd=="test-label"?"":" (if -, read from stdin)")<<"\n"
  "  <k>          (optional; 1 by default) predict top k labels\n"
  "  <th>         (optional; 0.0 by default) probability threshold\n\n\n";
 }else if(cmd=="nn"||cmd=="analogies"){
  o<<"usage: fasttext "<<cmd<<" <model> <k>\n\n  <model>      model filename\n  <k>          (optional; 10 by default) predict top k labels\n\n";
 }else if(cmd=="dump")o<<"usage: fasttext dump <model> <option>\n\n  <model>      model filename\n  <option>     option from args,dict,input,output\n";
 else if(cmd=="print-ngrams")o<<"usage: fasttext print-ngrams <model> <word>\n\n  <model>      model filename\n  <word>       word to print\n\n\n";
 else o<<"usage: fasttext "<<cmd<<" <model>\n\n  <model>      model filename\n\n\n";
}
void dumpModel(const Model&m,const string&what){
 auto&a=m.a;
 if(what=="args"){
  cout<<"dim "<<a.dim<<"\nws "<<a.ws<<"\nepoch "<<a.epoch<<"\nminCount "<<a.minCount<<"\nneg "<<a.neg<<"\nwordNgrams "<<a.wordNgrams<<"\nloss "<<a.lossName()<<"\nmodel "<<a.modelName()<<"\nbucket "<<a.bucket<<"\nminn "<<a.minn<<"\nmaxn "<<a.maxn<<"\nlrUpdateRate "<<a.lrUpdateRate<<"\nt "<<a.t<<"\n";
 }else if(what=="dict"){cout<<m.d.words.size()<<"\n";for(auto&e:m.d.words)cout<<e.word<<" "<<e.count<<" "<<(e.type?"label":"word")<<"\n";}
 else if(what=="input")m.input.dump(cout);else if(what=="output")m.output.dump(cout);
 else{shortHelp("dump");exit(1);}
