void testing(Model&m,istream&in,int k,float threshold,bool byLabel){
 vector<int64_t>truth(m.d.nlabels),pred(m.d.nlabels),correct(m.d.nlabels);int64_t examples=0,allTruth=0,allPred=0,allCorrect=0;
 in.clear();in.seekg(0);
 while(in.peek()!=EOF){vector<int>w,l;m.d.line(in,w,l);if(w.empty()||l.empty())continue;auto result=m.predict(w,k,threshold);examples++;allTruth+=l.size();allPred+=result.size();for(int x:l)truth[x]++;for(auto&p:result){pred[p.second]++;if(find(l.begin(),l.end(),p.second)!=l.end()){correct[p.second]++;allCorrect++;}}}
 if(byLabel){
  auto number=[](double x){if(isnan(x))cout<<"--------";else cout<<fixed<<setprecision(6)<<x;};
  for(int i=0;i<m.d.nlabels;i++){
   cout<<"F1-Score : ";number(truth[i]+pred[i]?2.0*correct[i]/(truth[i]+pred[i]):numeric_limits<double>::quiet_NaN());cout<<"  Precision : ";number(pred[i]?double(correct[i])/pred[i]:numeric_limits<double>::quiet_NaN());cout<<"  Recall : ";number(truth[i]?double(correct[i])/truth[i]:numeric_limits<double>::quiet_NaN());cout<<"   "<<m.d.words[i+m.d.nwords].word<<"\n";
  }
 }
 double p=allPred?double(allCorrect)/allPred:numeric_limits<double>::quiet_NaN(),r=allTruth?double(allCorrect)/allTruth:numeric_limits<double>::quiet_NaN();
 cout<<setprecision(3)<<"N\t"<<examples<<"\nP@"<<k<<"\t"<<p<<"\nR@"<<k<<"\t"<<r<<"\n";
}
void nearest(Model&m,int k,bool analogies){
 vector<vector<float>>wv;wv.reserve(m.d.nwords);for(int i=0;i<m.d.nwords;i++){auto v=m.wordVector(m.d.words[i].word);float n=norm(v);if(n>0)mulVector(v,1/n);wv.push_back(move(v));}
 auto query=[&](vector<float>&v,const set<string>&ban){float n=norm(v);if(n<1e-8)n=1;vector<pair<float,string>>heap;auto cmp=[](const pair<float,string>&a,const pair<float,string>&b){return a.first>b.first;};
  for(int i=0;i<m.d.nwords;i++){
   const string&w=m.d.words[i].word;float score=dot(v.data(),wv[i].data(),m.a.dim)/n;
   if(heap.size()==(size_t)k&&score<heap.front().first)continue;if(ban.count(w))continue;
   heap.emplace_back(score,w);push_heap(heap.begin(),heap.end(),cmp);if(heap.size()>(size_t)k){pop_heap(heap.begin(),heap.end(),cmp);heap.pop_back();}
  }sort_heap(heap.begin(),heap.end(),cmp);for(auto&p:heap)cout<<p.second<<" "<<p.first<<"\n";
 };
 if(!analogies){string w;while(true){cout<<"Query word? "<<flush;if(!(cin>>w))break;auto v=m.wordVector(w);query(v,{w});}}
 else {string x,y,z;while(true){cout<<"Query triplet (A - B + C)? "<<flush;if(!(cin>>x>>y>>z))break;auto v=m.wordVector(x),b=m.wordVector(y),c=m.wordVector(z);addVector(v,b.data(),-1);addVector(v,c.data());query(v,{x,y,z});}}
}
int main(int argc,char**argv){
 if(argc<2){cerr<<generalHelp;return 1;}string cmd=argv[1];
 if(cmd=="supervised"||cmd=="skipgram"||cmd=="cbow"){
  Model m;m.a.parse(argc,argv);m.train();return 0;
 }
 if(cmd=="quantize"){
  Args args;if(argc==2){cerr<<"usage: fasttext quantize <args>\n\n";args.help(cerr);return 1;}args.parse(argc,argv);Model m;m.load(args.output+".bin");
  if(m.a.model!=3)throw invalid_argument("For now we only support quantization of supervised models");
  if(m.input.m<256||(args.cutoff>0&&args.cutoff<256)||(args.qout&&m.output.m<256))throw invalid_argument("Matrix too small for quantization, must have at least 256 rows");
  m.save(args.output+".ftz");return 0;
 }
 set<string> commands={"test","test-label","predict","predict-prob","print-word-vectors","print-sentence-vectors","print-ngrams","nn","analogies","dump"};
 if(!commands.count(cmd)){cerr<<generalHelp;return 1;}
 bool eval=cmd=="test"||cmd=="test-label"||cmd=="predict"||cmd=="predict-prob";
 bool nn=cmd=="nn"||cmd=="analogies";
 int lo=eval?4:nn?3:(cmd=="print-ngrams"||cmd=="dump")?4:3;
 int hi=eval?6:nn?4:lo;
 if(argc<lo||argc>hi){shortHelp(cmd);return 1;}
 Model m;
 // The optional numeric arguments are parsed before loading the model.
 int k=eval?(argc>4?stoi(argv[4]):1):nn?(argc>3?stoi(argv[3]):10):1;
 float th=eval&&argc>5?stof(argv[5]):0;
 m.load(argv[2]);
 if(cmd=="dump"){dumpModel(m,argv[3]);return 0;}
 if(cmd=="print-word-vectors"){string w;while(cin>>w){cout<<w<<" ";printVector(cout,m.wordVector(w));}return 0;}
 if(cmd=="print-sentence-vectors"){while(cin.peek()!=EOF)printVector(cout,m.sentence(cin));return 0;}
 if(cmd=="print-ngrams"){
  string w=argv[3];vector<int>v;vector<string>names;int idx=m.d.id(w);if(idx>=0){v.push_back(idx);names.push_back(w);}if(w!="</s>")m.d.ngrams(w,v,&names);
  for(size_t i=0;i<v.size();i++){vector<float>x(m.a.dim,0);if(v[i]>=0&&v[i]<m.input.m)addVector(x,m.input.row(v[i]));cout<<names[i]<<" ";printVector(cout,x);}return 0;
 }
 if(nn){nearest(m,k,cmd=="analogies");return 0;}
 string name=argv[3];ifstream file;istream*in=&cin;if(name!="-"){file.open(name);in=&file;}if(!*in){cerr<<(cmd=="test"||cmd=="test-label"?"Test file cannot be opened!\n":"Input file cannot be opened!\n");return 1;}
 if(cmd=="test"||cmd=="test-label")testing(m,*in,k,th,cmd=="test-label");
 else {while(in->peek()!=EOF){vector<int>w,l;m.d.line(*in,w,l);auto p=m.predict(w,k,th);for(size_t i=0;i<p.size();i++){if(i)cout<<" ";cout<<m.d.words[m.d.nwords+p[i].second].word;if(cmd=="predict-prob")cout<<" "<<exp(p[i].first);}cout<<"\n";}}
 return 0;
}
