void testing(Model&m,istream&in,int k,float threshold,bool byLabel){
 vector<int64_t>truth(m.d.nlabels),pred(m.d.nlabels),correct(m.d.nlabels);int64_t examples=0,allTruth=0,allPred=0,allCorrect=0;
