 while(in.peek()!=EOF){vector<int>w,l;m.d.line(in,w,l);if(w.empty()||l.empty())continue;auto result=m.predict(w,k,threshold);examples++;allTruth+=l.size();allPred+=result.size();for(int x:l)truth[x]++;for(auto&p:result){pred[p.second]++;if(find(l.begin(),l.end(),p.second)!=l.end()){correct[p.second]++;allCorrect++;}}}
