void nearest(Model&m,int k,bool analogies){
 vector<vector<float>>wv;wv.reserve(m.d.nwords);for(int i=0;i<m.d.nwords;i++){auto v=m.wordVector(m.d.words[i].word);float n=norm(v);if(n>0)mulVector(v,1/n);wv.push_back(move(v));}
 auto query=[&](vector<float>&v,const set<string>&ban){float n=norm(v);if(n<1e-8)n=1;vector<pair<float,string>>heap;auto cmp=[](const pair<float,string>&a,const pair<float,string>&b){return a.first>b.first;};
  for(int i=0;i<m.d.nwords;i++){
   const string&w=m.d.words[i].word;float score=dot(v.data(),wv[i].data(),m.a.dim)/n;
   if(heap.size()==(size_t)k&&score<heap.front().first)continue;if(ban.count(w))continue;
   heap.emplace_back(score,w);push_heap(heap.begin(),heap.end(),cmp);if(heap.size()>(size_t)k){pop_heap(heap.begin(),heap.end(),cmp);heap.pop_back();}
  }sort_heap(heap.begin(),heap.end(),cmp);for(auto&p:heap)cout<<p.second<<" "<<p.first<<"\n";
 };
 if(!analogies){string w;while(true){cout<<"Query word? "<<flush;if(!(cin>>w))break;auto v=m.wordVector(w);query(v,{w});}}
 else {string x,y,z;while(true){cout<<"Query triplet (A - B + C)? "<<flush;if(!(cin>>x>>y>>z))break;auto v=m.wordVector(x),b=m.wordVector(y),c=m.wordVector(z);addVector(v,b.data(),-1);addVector(v,c.data());query(v,{x,y,z});}}
}
