// A compact subspace codebook, stored as one byte per row and subspace.
struct ProductCodes {
 int dim=0,nsub=0,dsub=0,last=0;
 vector<float>centroids;
 void save(ostream&o)const{put<int32_t>(o,dim);put<int32_t>(o,nsub);put<int32_t>(o,dsub);put<int32_t>(o,last);o.write(reinterpret_cast<const char*>(centroids.data()),centroids.size()*sizeof(float));}
 void load(istream&in){dim=get<int32_t>(in);nsub=get<int32_t>(in);dsub=get<int32_t>(in);last=get<int32_t>(in);if(dim<0||dim>1000000||nsub<0||dsub<0)throw invalid_argument("Invalid codebook.");centroids.resize(dim*256);in.read(reinterpret_cast<char*>(centroids.data()),centroids.size()*sizeof(float));}
 int subdim(int s)const{return s==nsub-1?last:dsub;}
 float* center(int s,int c){return centroids.data()+s*dsub*256+c*subdim(s);}
 const float*center(int s,int c)const{return centroids.data()+s*dsub*256+c*subdim(s);}
 vector<uint8_t> encode(const Matrix&m,int ds){
  dim=m.n;dsub=ds;nsub=(dim+ds-1)/ds;last=dim-(nsub-1)*ds;centroids.assign(dim*256,0);vector<uint8_t>code(m.m*nsub);
  minstd_rand rng(1234);
  for(int s=0;s<nsub;s++){
   int n=subdim(s),offset=s*dsub;
   vector<vector<float>>unique;
   map<vector<float>,int>seen;
   for(int i=0;i<m.m&&unique.size()<=256;i++){vector<float>v(m.row(i)+offset,m.row(i)+offset+n);if(!seen.count(v)){seen[v]=unique.size();unique.push_back(v);}}
   if(unique.size()<=256){
    for(int i=0;i<(int)unique.size();i++)copy(unique[i].begin(),unique[i].end(),center(s,i));
    for(int i=0;i<m.m;i++){vector<float>v(m.row(i)+offset,m.row(i)+offset+n);code[i*nsub+s]=seen[v];}
   }else{
    // Lloyd iterations over a deterministic, shuffled set of training rows.
    vector<int>perm(m.m);iota(perm.begin(),perm.end(),0);shuffle(perm.begin(),perm.end(),rng);
    int trainCount=min<int64_t>(m.m,65536);
    for(int c=0;c<256;c++)copy(m.row(perm[c])+offset,m.row(perm[c])+offset+n,center(s,c));
    auto nearest=[&](const float*v){int best=0;float dist=numeric_limits<float>::infinity();for(int c=0;c<256;c++){const float*ctr=center(s,c);float dd=0;for(int j=0;j<n;j++){float z=v[j]-ctr[j];dd+=z*z;}if(dd<dist){best=c;dist=dd;}}return best;};
    vector<float>sums(256*n);vector<int>counts(256);
    for(int it=0;it<25;it++){
     fill(sums.begin(),sums.end(),0);fill(counts.begin(),counts.end(),0);
     for(int i=0;i<trainCount;i++){const float*v=m.row(perm[i])+offset;int c=nearest(v);counts[c]++;for(int j=0;j<n;j++)sums[c*n+j]+=v[j];}
     for(int c=0;c<256;c++){
      if(counts[c]){for(int j=0;j<n;j++)center(s,c)[j]=sums[c*n+j]/counts[c];}
      else {int row=perm[(it*256+c)%trainCount];copy(m.row(row)+offset,m.row(row)+offset+n,center(s,c));}
     }
    }
    for(int i=0;i<m.m;i++)code[i*nsub+s]=nearest(m.row(i)+offset);
   }
  }
  return code;
 }
};
struct QuantizedMatrix {
 bool qnorm=false;int64_t m=0,n=0;vector<uint8_t>codes,normCodes;ProductCodes pq,normPq;
 void create(const Matrix&src,int dsub,bool normalize){
  if(src.m<256)throw invalid_argument("Matrix too small for quantization, must have at least 256 rows");
