python3 - <<'PY'
import subprocess,select,os,time,collections
cases=[('.observations/supng.bin',['good nice bad','happy sad good','awful bad nice']),('.observations/sgfull.bin',['one two three','two four five','three five one']),('.observations/features-ngrams.bin',['alpha beta gamma','unknown ça last']),('.observations/learnlabels-softmax.bin',['x y z','z x q'])]
for mode in ['a','n']:
 errors=collections.Counter();count=0
 for model,queries in cases:
  if mode=='n':queries=list(dict.fromkeys(' '.join(queries).split()))
  data=('\n'.join(queries)+'\n').encode()
  if mode=='a':
   p=subprocess.Popen(['./executable','analogies',model,'100'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE);p.stdin.write(data);p.stdin.flush();out=b'';start=time.time()
   prompt=b'Query triplet (A - B + C)? '
   while out.count(prompt)<len(queries)+1 and time.time()-start<5:
    if select.select([p.stdout],[],[],.1)[0]:out+=os.read(p.stdout.fileno(),8192)
   p.kill();p.communicate()
  else:
   out=subprocess.check_output(['./executable','nn',model,'100'],input=data);prompt=b'Query word? '
  ref=[x.decode().strip() for x in out.split(prompt)[1:-1]]
  ours=subprocess.check_output(['.observations/neighbor_probe',model,mode],input=data).decode().split('END\n')[:-1]
  nmode=30 if mode=='a' else 6
  for i,r in enumerate(ref):
   for output in ours[i*nmode:(i+1)*nmode]:
    key,body=output.split('\n',1);body=body.strip()
    errors[key]+=sum(x!=y for x,y in zip(r.splitlines(),body.splitlines()))
   count+=len(r.splitlines())
 print(mode,'total scored neighbors',count,'mismatches',sorted(errors.items(),key=lambda x:x[1]))
PY"}

